package com.hirain.aiagent.rag.policy;
import org.junit.Test;import static org.junit.Assert.*;
/** 无依据时强制 Tool；仅当前请求中记录到可靠 Evidence 后才允许文本收口。 */
public class KnowledgeLoopPolicyTest {@Test public void requiresToolUntilCurrentRequestHasEvidence(){KnowledgeLoopPolicy policy=new KnowledgeLoopPolicy();KnowledgeRequestState state=new KnowledgeRequestState();KnowledgeIntentDecision required=new KnowledgeIntentDecision(KnowledgeRequirement.REQUIRED,"test","v1",false);assertTrue(policy.beforeModel(required,state).toolRequired());state.recordOutcome("EVIDENCE","HYBRID");assertFalse(policy.beforeModel(required,state).toolRequired());}@Test public void stopsAfterTwoEvidenceFreeQueries(){KnowledgeRequestState state=new KnowledgeRequestState();KnowledgeIntentDecision required=new KnowledgeIntentDecision(KnowledgeRequirement.REQUIRED,"test","v1",false);state.tryBeginInvocation(0,"one");state.recordOutcome("NO_EVIDENCE","NONE");state.tryBeginInvocation(1,"two");state.recordOutcome("NO_EVIDENCE","NONE");assertTrue(new KnowledgeLoopPolicy().evidenceExhausted(required,state));}}
